import { NextResponse } from "next/server";
import { GALLERY_LOADERS } from "@/lib/gallery/galleryIndex.generated";

/**
 * GET /visuals/<subject>/thumbs (2026-11-23): one subject's tile pictures,
 * slug -> static markup (generated by `npm run gallery:index`). Apart from the
 * page so the pictures travel once and the browser keeps them: inside the
 * page's own data Next would send them twice (HTML and page data), ~240 KB
 * compressed for JEE Physics. Cached, reads nothing about the visitor.
 */
export const revalidate = 86400;
export const dynamic = "force-static";

export function generateStaticParams() {
  return [];
}

export async function GET(_request: Request, { params }: { params: Promise<{ subjectRoute: string }> }) {
  const { subjectRoute } = await params;
  const load = GALLERY_LOADERS[subjectRoute];
  if (!load) return NextResponse.json({ error: "Unknown subject." }, { status: 404 });
  const { THUMBS } = await load();
  return NextResponse.json(THUMBS, {
    headers: { "Cache-Control": "public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800" },
  });
}
